list_dashboard_banners.code:
import com.webcommander.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.dashboardBanners().listDashboardBanners();
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("banners")) {
    Map<?, ?> banner = (Map<?, ?>) row;
    System.out.println(banner.get("key") + " " + banner.get("title") + " " + banner.get("active") + " " + banner.get("position"));
}

