ApiResponse response = client.dashboardBanners().createDashboardBanner(Map.of(
        "key", "spring_sale", "title", "Spring sale", "description", "Ends Friday.",
        "tags", List.of("Sales"), "icon", "tag",
        "learn_more", Map.of("action", "open_link", "label", "Learn more", "url", "https://example.com/spring-sale")));
Map<?, ?> banner = (Map<?, ?>) response.getMap();
System.out.println(banner.get("key") + " " + banner.get("title") + " " + banner.get("active") + " " + banner.get("position"));

